('a6180c06-17c6-5aa9-a538-cc606e05fbc1', 'Standing Single Leg Curl', 'legs', 'knee_dominant', 'isolation', ARRAY['Hamstrings']::text[], ARRAY[]::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Attach ankle strap to low cable; stand facing the stack','Keep the working knee aligned with the standing knee — don''t flare it','Control the extension; don''t let the weight snap the leg straight']::text[], ARRAY['Swinging the hip to complete the rep','Not fully extending the leg on the eccentric','Using too much weight — hamstrings are strong, but isolation requires control']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('2e6990e5-7c9b-5c34-a4bb-727b9756098c', 'Decline Dumbbell Press', 'push', 'horizontal_push', 'compound', ARRAY['Lower Chest']::text[], ARRAY['Triceps','Front Deltoid']::text[], ARRAY['Dumbbells','Decline Bench']::text[], 'weight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Set feet securely on the pad; 15-30° decline angle','DBs at chest level, not shoulders — the decline already shifts the vector','Press to full extension but don''t lose chest tension at lockout']::text[], ARRAY['Excessive decline — over 45° causes shoulder discomfort','Letting DBs drift toward the head','Rushing the eccentric phase']::text[], 3, '10-12', 90, 'Exercise science', true, false, now()),
('1ed7a7d4-ab9b-5054-839a-12344b8e0473', 'Incline Dumbbell Fly', 'push', 'horizontal_push', 'isolation', ARRAY['Upper Chest']::text[], ARRAY['Front Deltoid']::text[], ARRAY['Dumbbells','Incline Bench']::text[], 'weight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Slight permanent bend in the elbow — DO NOT straighten arms','Open wide enough for a strong pec stretch; stop before shoulder discomfort','Think ''hugging a barrel'' — arc motion, not a pressing motion']::text[], ARRAY['Straightening elbows — converts fly to press, removes pec stretch','Going too heavy — the fly is a stretch exercise, not a strength move','Bouncing at the bottom — high injury risk']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('49d24654-5b7f-5991-b9d4-b07fb0c2ae1a', 'Deficit Push-Up', 'push', 'horizontal_push', 'compound', ARRAY['Chest']::text[], ARRAY['Triceps','Front Deltoid']::text[], ARRAY['Bodyweight']::text[], 'bodyweight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Hands on push-up handles, books, or parallettes — feet on a flat surface','Lower until chest is well below hand level for maximum pec stretch','Elbows at 45° — not flared wide, not tucked tight']::text[], ARRAY['Hands too close together — reduces chest ROM','Sagging hips — maintain a rigid plank from head to heel','Bouncing at the bottom of the stretch']::text[], 3, '10-15', 75, 'Exercise science', true, false, now()),
('0e08eaa2-85e1-5fe2-b93d-75984b2c51d8', 'Floor Press', 'push', 'horizontal_push', 'compound', ARRAY['Chest']::text[], ARRAY['Triceps','Front Deltoid']::text[], ARRAY['Dumbbells']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Lie on the floor; upper arms rest on the floor at the bottom of each rep','Elbows stop at floor — never bounce; pause 1 second before pressing','Excellent for shoulder safety — limited ROM removes the risky stretched position']::text[], ARRAY['Letting elbows slam to the floor rather than softly touching','Arching the lower back excessively off the floor','Using bench-press grip width — go slightly narrower for floor press']::text[], 3, '10-12', 90, 'Exercise science', true, true, now()),
('4a89bb28-646a-54ab-9c51-e7fa3711cd3c', 'Machine Lateral Raise', 'push', 'shoulder_isolation', 'isolation', ARRAY['Lateral Delts']::text[], ARRAY[]::text[], ARRAY['Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Set the arm pad just below the elbow — not on the wrist','Slight forward lean on the machine targets the lateral delt more precisely','Lead with the elbow, not the wrist — think ''push elbow up to the ceiling''']::text[], ARRAY['Going too heavy and shrugging — trap dominance will mask delt work','Not reaching full lateral height — 90° or slightly above','Jerking the weight up with momentum']::text[], 4, '15-20', 60, 'Exercise science', true, false, now()),
('b57bd273-601f-5903-b412-2015c8d9882f', 'Cable Front Raise', 'push', 'shoulder_isolation', 'isolation', ARRAY['Front Delts']::text[], ARRAY['Lateral Delts']::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Attach a bar or handle to a low cable; stand facing away','Raise arm to shoulder height — going higher increases trap and neck recruitment','Slight elbow bend; keep the arm aligned with the front delt angle (30° off sagittal)']::text[], ARRAY['Swinging the torso to initiate the raise','Raising beyond 90° — diminishing returns and higher impingement risk','Letting the weight pull the arm straight back — control the eccentric']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('252c6a67-ea94-5194-9381-1c2fbeff8017', 'Egyptian Lateral Raise', 'push', 'shoulder_isolation', 'isolation', ARRAY['Lateral Delts']::text[], ARRAY[]::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Stand sideways to a low cable; hold a fixed support with the other hand and lean away','The tilt increases the ROM in the lengthened position — peak stretch at the bottom','Raise the arm in the scapular plane (30° forward) — not directly sideways']::text[], ARRAY['Not leaning far enough — the lean is what makes the lengthened-position superior','Going too fast on the eccentric — the slow lower is where the growth signal lives','Arm drifting in front of the body — stay in the scapular plane']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('7350d6dc-0b61-5349-89b8-f783be5a1b63', 'Bench Dips', 'push', 'elbow_extension', 'compound', ARRAY['Triceps']::text[], ARRAY['Front Deltoid','Chest']::text[], ARRAY['Bodyweight']::text[], 'bodyweight_reps', 'beginner', ARRAY['Beginner','Intermediate']::text[], ARRAY['Hands shoulder-width on the bench edge; hips close to the bench','Elbows point backward — not flared — to keep tension on the triceps','Lower until upper arm is parallel to the floor; don''t go below 90° shoulder']::text[], ARRAY['Dipping too deep — causes shoulder impingement','Elbows flaring sideways — shifts load off triceps','Hips drifting far out — increases shoulder stress']::text[], 3, '12-15', 60, 'Exercise science', true, true, now()),
('4807f154-f5f5-5a48-8dad-9fb7d7308f8d', 'Dumbbell Kickback', 'push', 'elbow_extension', 'isolation', ARRAY['Triceps']::text[], ARRAY[]::text[], ARRAY['Dumbbells']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Upper arm locked parallel to the floor and torso — ONLY the forearm moves','Extend fully — the tricep contracts hardest in the extended-arm position','Hinge forward 45-60° and brace the core to protect the lower back']::text[], ARRAY['Upper arm dropping — loses tension on the tricep entirely','Swinging the weight with shoulder momentum','Not achieving full elbow extension — partial reps underutilise the long head']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('c4e46bd5-9a98-5806-bd0e-26dec091c017', 'Overhead Cable Extension', 'push', 'elbow_extension', 'isolation', ARRAY['Triceps (Long Head)']::text[], ARRAY[]::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Face away from the stack; grab rope overhead with both hands behind the head','Keep elbows pointing directly upward — don''t let them flare outward','Full extension above the head; feel the long head stretch at the bottom']::text[], ARRAY['Elbows flaring out wide — removes long-head focus','Arching the lower back — engage core tightly','Using too much weight and sacrificing the stretch at the bottom']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('0916f91b-33e0-579f-9e1d-269520b60e47', 'Close-Grip Bench Press', 'push', 'elbow_extension', 'compound', ARRAY['Triceps']::text[], ARRAY['Chest','Front Deltoid']::text[], ARRAY['Barbell','Bench']::text[], 'weight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Grip just inside shoulder width — narrower than bench press but NOT touching','Elbows track close to the torso; elbow angle 20-30° from the body','Bar touches lower chest — NOT the same touch point as bench press']::text[], ARRAY['Grip too narrow — wrist strain and reduced force output','Elbows flaring wide — converts to a chest exercise','Partial reps at the top — full lockout is where tricep finishes the rep']::text[], 4, '8-12', 90, 'Exercise science', true, false, now()),
('3e779506-738c-5bd5-8604-430535d58a57', 'Rope Hammer Curl', 'pull', 'elbow_flexion', 'isolation', ARRAY['Biceps','Brachialis']::text[], ARRAY['Brachioradialis']::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Neutral (thumbs-up) grip throughout — do NOT supinate','Elbows pinned to sides; only the forearm moves','Squeeze hard at the top; control the cable on the way down']::text[], ARRAY['Supinating at the top — that would make it a standard curl, not hammer','Elbows drifting forward — loses brachialis tension','Too much wrist flexion at the top']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('5619c565-c271-5fcf-9974-d6fee4c838d9', 'High Cable Curl', 'pull', 'elbow_flexion', 'isolation', ARRAY['Biceps']::text[], ARRAY[]::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Set cables at head height; face the cable stack; curl toward your ears','Upper arm stays parallel to the floor — elbows fixed in space','Feel the bicep stretch at the start (arm extended forward) and squeeze at peak contraction']::text[], ARRAY['Elbow dropping below head height — loses the lengthened-position advantage','Using both arms asymmetrically — if using two cables, keep motion symmetrical','Jerking the curl — smooth constant tension is the goal']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('b9f70d8e-7a20-5701-a94b-9cd9068ce767', 'Pendlay Row', 'pull', 'horizontal_pull', 'compound', ARRAY['Lats (Thickness)','Mid Back']::text[], ARRAY['Biceps','Rear Delts','Erector Spinae']::text[], ARRAY['Barbell']::text[], 'weight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Bar starts on the floor each rep — true dead-stop row (no bounce)','Torso nearly horizontal (10-20° above parallel) at the start','Explosive pull to lower chest; bar path is nearly vertical']::text[], ARRAY['Torso angle too upright — becomes a partial barbell row, not a Pendlay','Not resetting to the floor each rep — removes the strict dead-stop stimulus','Lower back rounding — brace hard before every pull']::text[], 4, '5-8', 120, 'Exercise science', true, false, now()),
('8b3318db-ad90-5e3d-9366-ddd84e01404a', 'Machine High Row', 'pull', 'vertical_pull', 'compound', ARRAY['Lats (Width)']::text[], ARRAY['Biceps','Rear Delts']::text[], ARRAY['Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Chest pad supports the torso; pull handles down toward the upper chest','Lead with the elbows; think ''elbows to pockets'' — not hands to chest','Full stretch at the top — let the lats lengthen completely before each rep']::text[], ARRAY['Pulling with biceps instead of driving elbows down','Not getting full overhead stretch — the lengthened position matters most','Leaning back excessively — keep chest on the pad']::text[], 3, '10-12', 75, 'Exercise science', true, false, now()),
('ff89388e-6d67-5999-9454-c7ea7f32dc3d', 'Machine Low Row', 'pull', 'horizontal_pull', 'compound', ARRAY['Mid Back (Thickness)']::text[], ARRAY['Biceps','Lats','Rear Delts']::text[], ARRAY['Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Chest on pad; pull handles toward the lower abdomen, elbows close to the body','Retract scapulae at the back of the movement — squeeze shoulder blades together','Controlled full stretch forward — don''t lose the mid-back tension']::text[], ARRAY['Shrugging the traps instead of retracting the scapulae','Bouncing out of the stretched position — slow, controlled eccentric','Pulling too high — row to navel, not to chest']::text[], 3, '10-12', 75, 'Exercise science', true, false, now()),
('cc8a5340-063c-55b5-9784-47b14c2d5c82', 'Straight-Arm Pulldown', 'pull', 'vertical_pull', 'isolation', ARRAY['Lats']::text[], ARRAY['Teres Major','Core']::text[], ARRAY['Cable Machine']::text[], 'weight_reps', 'beginner', ARRAY['Beginner','Intermediate','Advanced']::text[], ARRAY['Arms stay straight the ENTIRE movement — this is NOT a lat pulldown','Hinge slightly at the hips; pull the bar in a sweeping arc from overhead to thighs','Think ''armpits to pockets'' — this movement is pure lat without bicep interference']::text[], ARRAY['Bending the elbows — converts to a lat pulldown and removes the isolation','Using too much weight and swinging the torso','Not reaching full overhead stretch at the start']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
('bb89a512-06d0-533d-b90f-997aada2c4fa', 'Captain''s Chair Leg Raise', 'core', 'core', 'isolation', ARRAY['Core']::text[], ARRAY['Hip Flexors']::text[], ARRAY['Machine']::text[], 'bodyweight_reps', 'intermediate', ARRAY['Intermediate','Advanced']::text[], ARRAY['Back flat against the pad; arms pressing down into the supports','Posterior pelvic tilt — tuck the pelvis BEFORE lifting; this switches hip flexors off','Raise knees to 90° for beginner; straight-leg raise for advanced']::text[], ARRAY['Swinging the legs with momentum — slow controlled reps only','Not tilting the pelvis — most of the work goes to hip flexors instead of abs','Lower back arching away from the pad']::text[], 3, '12-15', 60, 'Exercise science', true, false, now()),
